powerpages.fluentTokensCssExample:
:root {
  --colorBrandBackground: #0f6cbd;        /* brand.80 - primary */
  --colorBrandBackgroundHover: #115ea3;   /* brand.70 */
  --colorNeutralForeground1: #242424;     /* body text */
  --colorNeutralBackground1: #ffffff;     /* surface */
  --fontFamilyBase: 'Segoe UI', 'Segoe UI Web (West European)', -apple-system, BlinkMacSystemFont, Roboto, 'Helvetica Neue', sans-serif;
  --fontSizeBase300: 14px;
  --borderRadiusMedium: 4px;
}
body { font-family: var(--fontFamilyBase); color: var(--colorNeutralForeground1); }
.btn-primary {
  background-color: var(--colorBrandBackground);
  border-color: var(--colorBrandBackground);
  border-radius: var(--borderRadiusMedium);
}
.btn-primary:hover { background-color: var(--colorBrandBackgroundHover); }
/* Bootstrap 5 vars can point at Fluent tokens */
:root { --bs-primary: var(--colorBrandBackground); --bs-body-font-family: var(--fontFamilyBase); }

pcf.usePlatformThemeExample:
// index.ts (updateView)
public updateView(context: ComponentFramework.Context<IInputs>): React.ReactElement {
  const theme = context.fluentDesignLanguage?.tokenTheme ?? webLightTheme;
  return React.createElement(
    FluentProvider,
    { theme },
    React.createElement(HelloFluent, {
      label: context.parameters.label.raw ?? "Hello, Fluent 2!",
      onClick: () => this.notifyOutputChanged()
    })
  );
}
